style.css:
@-moz-document domain("youtube.com") {
/* --- 1. CORE VARIABLES --- */
    :root {
        cyber-red: #ff003c;     /* The main Neon Red */
        cyber-dark: #050505;    /* True Black */
        cyber-gray: #111111;    /* Panel Backgrounds */
        text-white: #ffffff;
    }

    /* --- 2. LIVE BACKGROUND (EDIT LINK BELOW) --- */
    html, [dark], ytd-app, #master-container {
        background-color: var(cyber-dark) !important;
        
        /* PASTE YOUR GIF LINK INSIDE THE QUOTES BELOW */
        background: url("https://media2.giphy.com/media/v1.Y2lkPTc5MGI3NjExZDV4eGN6cWVmcW9pZzBrMmhhdXMxbjdyb3R6eXdkdDg5cnJrMXVyMyZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/jx4jKhrKvifvCZtyN5/giphy.gif") no-repeat center center fixed !important;
        
        /* Adjusts how the GIF fits (cover = fill screen, contain = fit image) */
        background-size: cover !important;
        
        /* Make YouTube transparent so GIF shows through */
        yt-spec-base-background: transparent !important;
        yt-spec-brand-background-primary: transparent !important;
        yt-spec-raised-background: rgba(10, 10, 10, 0.9) !important; 
        yt-spec-menu-background: rgba(10, 10, 10, 0.9) !important;
        yt-spec-text-primary: var(text-white) !important;
    }

    /* --- 3. REPLICATED BUTTONS --- */
    /* Category Chips (Music, Gaming, etc.) */
    yt-chip-cloud-chip-renderer {
        background-color: rgba(0, 0, 0, 0.8) !important;
        border: 1px solid var(cyber-red) !important;
        border-radius: 4px !important;
        color: #fff !important;
        transition: 0.2s;
    }

    /* The "Selected" Chip (e.g., "All") */
    yt-chip-cloud-chip-renderer[selected] {
        background-color: #ffffff !important;
        color: #000000 !important;
        border: 1px solid #fff !important;
        font-weight: bold;
        box-shadow: 0 0 10px rgba(255,255,255,0.5);
    }

    /* Hover Effect */
    yt-chip-cloud-chip-renderer:hover:not([selected]) {
        background-color: var(cyber-red) !important;
        box-shadow: 0 0 15px var(cyber-red);
    }

    /* Standard Buttons */
    yt-button-shape, button.yt-spec-button-shape-next {
        border: 1px solid var(cyber-red) !important;
        background: rgba(0,0,0,0.5) !important; /* Slight dark tint for readability */
        color: var(cyber-red) !important;
        border-radius: 4px !important;
    }

    /* --- 4. RED SEARCH BAR & HEADER --- */
    #masthead-container {
        background: rgba(5, 5, 5, 0.95) !important;
        border-bottom: 2px solid var(cyber-red);
        box-shadow: 0 0 15px rgba(255, 0, 60, 0.2);
    }

    #search-form #container {
        background: #000 !important;
        border: 1px solid var(cyber-red) !important;
        box-shadow: inset 0 0 5px rgba(255, 0, 60, 0.3);
    }

    /* Search Button */
    #search-icon-legacy {
        background: var(cyber-red) !important;
        border: 1px solid var(cyber-red) !important;
    }
    #search-icon-legacy yt-icon {
        color: #fff !important;
    }

    /* --- 5. SIDEBAR (Red Icons) --- */
    ytd-guide-entry-renderer yt-icon, 
    ytd-mini-guide-renderer yt-icon {
        color: var(cyber-red) !important;
        fill: var(cyber-red) !important;
    }
    
    #guide-content, ytd-mini-guide-renderer {
        background: rgba(5,5,5,0.95) !important;
        border-right: 1px solid #333;
    }

    /* --- 6. VIDEO PLAYER & PROGRESS --- */
    .ytp-play-progress {
        background: var(cyber-red) !important;
        box-shadow: 0 0 15px var(cyber-red);
    }
    
    .ytp-scrubber-button {
        background: #fff !important;
        border: 2px solid var(cyber-red);
        transform: scale(1.2);
    }

    /* --- 7. LOGO CUSTOMIZATION --- */
    ytd-topbar-logo-renderer #logo-icon {
        filter: grayscale(100%) brightness(100%) drop-shadow(0 0 2px var(cyber-red));
    }
    ytd-topbar-logo-renderer #logo-icon g path:nth-child(1) {
        fill: var(cyber-red) !important;
    }
}
